/* Nike DNA — athletic black/white, condensed uppercase display, volt accent */
.theme-nike-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.970 0 0);
  --surface-2: oklch(0.12 0 0);
  --fg: oklch(0.178 0 0);
  --fg-muted: oklch(0.546 0.003 286.3);
  --accent: oklch(0.178 0 0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.528 0.262 263.8);
  --line: oklch(0.85 0 0);
  --success: oklch(0.675 0.179 147.6);
  --warning: oklch(0.803 0.162 74.7);
  --danger: oklch(0.58 0.22 27);

  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;

  --shadow-1: none;
  --shadow-2: 0 10px 30px -14px oklch(0 0 0 / 40%);
  --shadow-3: 0 24px 60px -24px oklch(0 0 0 / 55%);
  --glow: 0 0 0 3px var(--accent);

  --border-width: 2px;
  --blur-amount: 0px;

  --font-display: "Oswald", "Arial Narrow", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: 0.005em;
  --label-transform: uppercase;
  --label-tracking: 0.12em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-nike-dna h1,
.theme-nike-dna h2,
.theme-nike-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  text-transform: uppercase;
  font-weight: 400;
  line-height: 0.9;
}

.theme-nike-dna h1 {
  font-size: clamp(3.5rem, 10vw, 8rem);
}

.theme-nike-dna button {
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 700;
  border-radius: var(--radius-pill);
}

/* signature */
.theme-nike-dna { --font-ui: var(--font-display); }
.theme-nike-dna h1, .theme-nike-dna h2 { text-transform: uppercase; font-style: italic; }
.theme-nike-dna button { text-transform: uppercase; font-weight: 600; letter-spacing: 0.02em; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
